// zcode colour presets. The preset palettes themselves live in
// /custom-themes.css (generated by the `zcode-theme` CLI — the single source of
// truth) as `[data-zcode-preset="<id>"] { ...vars }` blocks plus a
// `:root { --zc-presets: "id:Label:dark|..." }` catalogue. This module only
// reads that catalogue, toggles <html data-zcode-preset>, and persists the
// choice as a server-backed setting so it syncs across devices.
import { writeSetting } from './settings-store.js';

export const ZCODE_PRESET_KEY = 'pi-web:v1:zcode-preset';
export const OPEN_PICKER_EVENT = 'pi:open-theme-picker';
export const ZCODE_ACT_KEY = 'pi-web:v1:zcode-act';

// Action-colour schemes (independent of the background preset). Catalogue is
// `--zc-act-schemes: "id:Label|..."` in /custom-themes.css; each scheme is a
// `html[data-zcode-act="<id>"]` block overriding --act-* and markdown accents.
export function listActSchemes(doc = document) {
  let raw;
  try {
    raw = getComputedStyle(doc.documentElement).getPropertyValue('--zc-act-schemes') || '';
  } catch {
    return [];
  }
  raw = raw.trim().replace(/^["']|["']$/g, '');
  if (!raw) return [];
  return raw
    .split('|')
    .map((item) => {
      const [id, label] = item.split(':');
      return id ? { id: id.trim(), label: (label || id).trim() } : null;
    })
    .filter(Boolean);
}

export function currentActScheme(doc = document) {
  return doc.documentElement.dataset.zcodeAct || '';
}

export function applyActScheme(id, { doc = document, persist = true } = {}) {
  const clean = String(id || '').replace(/[^a-z0-9-]/g, '');
  if (clean) doc.documentElement.dataset.zcodeAct = clean;
  else delete doc.documentElement.dataset.zcodeAct;
  if (persist) writeSetting(ZCODE_ACT_KEY, clean);
  try {
    doc.defaultView?.dispatchEvent(new CustomEvent('pi:zcode-act-change', { detail: clean }));
  } catch {}
}

export function listPresets(doc = document) {
  let raw;
  try {
    raw = getComputedStyle(doc.documentElement).getPropertyValue('--zc-presets') || '';
  } catch {
    return [];
  }
  raw = raw.trim().replace(/^["']|["']$/g, '');
  if (!raw) return [];
  return raw
    .split('|')
    .map((item) => {
      const [id, label, mode] = item.split(':');
      return id ? { id: id.trim(), label: (label || id).trim(), mode: (mode || 'dark').trim() } : null;
    })
    .filter(Boolean);
}

export function currentPreset(doc = document) {
  return doc.documentElement.dataset.zcodePreset || '';
}

function syncChrome(doc) {
  try {
    const bg = getComputedStyle(doc.documentElement).getPropertyValue('--body-bg').trim();
    if (bg) {
      doc.documentElement.style.backgroundColor = bg;
      doc.querySelectorAll('meta[name="theme-color"]').forEach((m) => m.setAttribute('content', bg));
    }
  } catch {}
}

export function applyPreset(id, { doc = document, persist = true } = {}) {
  const clean = String(id || '').replace(/[^a-z0-9-]/g, '');
  if (clean) doc.documentElement.dataset.zcodePreset = clean;
  else delete doc.documentElement.dataset.zcodePreset;
  syncChrome(doc);
  if (persist) writeSetting(ZCODE_PRESET_KEY, clean);
  try {
    doc.defaultView?.dispatchEvent(new CustomEvent('pi:zcode-preset-change', { detail: clean }));
  } catch {}
}

// On boot: if the server did not inject a preset, fall back to localStorage.
export function bootPreset(doc = document) {
  if (!doc.documentElement.dataset.zcodeAct) {
    try {
      const a = localStorage.getItem(ZCODE_ACT_KEY);
      if (a) applyActScheme(a, { doc, persist: false });
    } catch {}
  }
  if (doc.documentElement.dataset.zcodePreset) {
    syncChrome(doc);
    return;
  }
  try {
    const v = localStorage.getItem(ZCODE_PRESET_KEY);
    if (v) applyPreset(v, { doc, persist: false });
  } catch {}
}

export function openThemePicker() {
  try {
    window.dispatchEvent(new CustomEvent(OPEN_PICKER_EVENT));
  } catch {}
}
